using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Workflows;using Namaa.Api.Extensions;namespace Namaa.Api.Controllers;[ApiController][Route("api")]public sealed class BusinessWorkflowsController(ISender sender):ControllerBase{
