[HttpPost("quotations/{id:long}/cancel")]public async Task<IActionResult>CancelQuotation(long id,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.Quotations.Commands.CancelQuotation.CancelQuotationCommand(id),cancellationToken)).ToActionResult(this);
[HttpPost("invoices/{id:long}/issue")]public async Task<IActionResult>IssueInvoice(long id,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.Invoices.Commands.IssueInvoice.IssueInvoiceCommand(id),cancellationToken)).ToActionResult(this);
