[HttpPost("payments/{id:long}/post")]public async Task<IActionResult>PostPayment(long id,TimestampRequest request,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.Payments.Commands.PostPayment.PostPaymentCommand(id,request.At),cancellationToken)).ToActionResult(this);
[HttpPost("payments/{id:long}/cancel")]public async Task<IActionResult>CancelPayment(long id,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.Payments.Commands.CancelPayment.CancelPaymentCommand(id),cancellationToken)).ToActionResult(this);
[HttpPost("payment-vouchers/{id:long}/post")]public async Task<IActionResult>PostVoucher(long id,TimestampRequest request,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.PaymentVouchers.Commands.PostPaymentVoucher.PostPaymentVoucherCommand(id,request.At),cancellationToken)).ToActionResult(this);
