[HttpPost("purchase-invoices/{id:long}/post")]public async Task<IActionResult>PostPurchaseInvoice(long id,TimestampRequest request,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.PurchaseInvoices.Commands.PostPurchaseInvoice.PostPurchaseInvoiceCommand(id,request.At),cancellationToken)).ToActionResult(this);
[HttpPost("purchase-invoices/{id:long}/cancel")]public async Task<IActionResult>CancelPurchaseInvoice(long id,CancellationToken cancellationToken)=>(await sender.Send(new Namaa.Application.PurchaseInvoices.Commands.CancelPurchaseInvoice.CancelPurchaseInvoiceCommand(id),cancellationToken)).ToActionResult(this);
}
